from collections import deque
def solve(g):
    h=len(g); w=len(g[0]); O=[r[:] for r in g]
    # gather equality groups among 2-cells under symmetry
    seen=[[False]*w for _ in range(h)]
    groups=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and not seen[i][j]:
                grp={(i,j)}; q=deque([(i,j)])
                while q:
                    a,b=q.popleft()
                    for n in [(a,23-b),(b,a)]:
                        if n not in grp and g[n[0]][n[1]]==2:
                            grp.add(n); q.append(n)
                groups.append(grp)
    # for each group, collect values from known cells via same-row/column constraints
    # simpler: assign any consistent value; use majority/mirror from neighboring known cells
    res=[r[:] for r in g]
    for grp in groups:
        cands=[]
        for i,j in grp:
            for ni,nj in [(i,23-j),(23-i,j),(23-i,23-j)]:
                val=g[ni][nj]
                if val!=2: cands.append(val)
        if len(set(cands))==1:
            v=cands[0]; 
            for i,j in grp: res[i][j]=v
        else:
            # use most common
            from collections import Counter
            c=Counter(cands)
            v=c.most_common(1)[0][0]
            for i,j in grp: res[i][j]=v
    return res
